const sentence: Record<Widget, (key: string) => string> = {
  dialog: (key) => `${key} closes the dialog. The close control is a button named Close and is in the tab order. The dialog can take focus without entering the tab order. In static HTML, that content uses tabindex -1. On React and Vue, focus returns to the trigger. A title names the dialog. The title is a level 2 heading. On React, in Vue, and in static HTML, the description is tied to the dialog. An open dialog is visible as Opened. A closed dialog has no open status. An omitted name is Dialog. In static HTML, the close control and Save are type button. On the mini program, the close mark is hidden from the name.`,
  sheet: (key) => `${key} closes the sheet. The close control is a button named Close and is in the tab order. The sheet can take focus without entering the tab order. In static HTML, that content uses tabindex -1. On React and Vue, focus returns to the trigger. A title names the sheet. The title is a level 2 heading. On React, in Vue, and in static HTML, the description is tied to the sheet. An open sheet is visible as Opened. A closed sheet has no open status. An omitted name is Sheet. The close icon is hidden from that name. On React, in Vue, and in static HTML, the trigger controls the sheet. On the mini program, the close mark is hidden from the name.`,
  select: (key) =>
    `${key} opens the list. ArrowDown and ArrowUp move the highlighted option. Home moves to the first enabled option. End moves to the last. A letter moves to the next enabled option whose label starts with that letter. An open list only moves the highlight for Home, End, and a letter. A closed list selects the option those keys land on. Enter selects the highlighted option. Escape closes the list. On the mini program, the close control is a button named Close and is in the tab order. The trigger is in the tab order unless it is disabled. Options are not. One selected option is visible as Option N of the option count. Several selected options read how many are selected. An empty value has no option status. On the mini program, an omitted name is the selected value, or Select an item. A passed aria-label names the trigger. On the mini program, the list is named by the trigger. The check mark on a selected option is not part of its name. The arrow on the trigger is not part of the name. Each option exposes whether it is selected. In static HTML, the closed list stays hidden and its content uses tabindex 0. In static HTML, the trigger is a button with aria-haspopup listbox. On the mini program, the trigger sets aria-haspopup listbox. On the mini program, aria-activedescendant is set only while an option is highlighted. On the mini program, aria-controls is set only while the popup is open. On the mini program, the open list uses tabindex 0. On the mini program, the close mark is hidden from the name.`,
  menu: (key) =>
    `${key} opens the menu. ArrowDown and ArrowUp move the highlighted item and skip a disabled item. Home moves to the first enabled item. End moves to the last. A letter moves to the next enabled item whose label starts with that letter and does not select it. A closed menu ignores that letter. Enter selects it. Escape closes the menu. The trigger names the menu. The trigger controls the menu. The trigger is in the tab order unless it is disabled. The highlighted item is visible as Item N of the item count. A closed menu has no item status. The highlighted item is in the tab order. The other items are not. On the mini program, the check mark beside a checkbox or radio item is not part of its name. The shortcut is hidden from the item name. In static HTML, the closed menu stays hidden and its content uses tabindex 0. On the mini program, aria-controls is set only while the popup is open. On the mini program, the open menu uses tabindex 0.`,
  tabs: (key) => `${key} selects the next tab and skips a disabled tab. Home selects the first enabled tab. End selects the last. The selected tab and its panel are in the tab order. The other tabs are not. In static HTML, the selected panel stays in the tab order. In static HTML, each tab is a button. The selected tab is visible as Tab N of the tab count. An empty value has no tab status. An omitted name is Tabs. A passed aria-label names the tab list. A disabled tab is not in the tab order. A disabled tab list leaves every tab out of the tab order. Each tab controls its panel. The panel is named by its tab. On the mini program, aria-controls is set only on the selected tab. On the mini program, a disabled tabs root sets aria-disabled.`,
  accordion: (key) =>
    `${key} moves to the next item without opening it and skips a disabled item. Home moves to the first enabled item. End moves to the last. Enter or Space opens the focused item. Each enabled trigger is in the tab order. One open item is visible as Item N of the item count. Several open items read how many are open. An empty value has no item status. A disabled item ignores those keys. A disabled accordion leaves every trigger out of the tab order. The marker beside a trigger is not part of its name. The trigger controls the panel. The panel is named by the trigger. On the mini program, aria-controls is set only while the panel is open.`,
  checkbox: (key) => `${key} toggles the checkbox. The checkbox is in the tab order unless it is disabled. On React and Vue, an omitted name is Checkbox. A passed aria-label names the checkbox. A checked box is visible as Checked. An indeterminate box is visible as Mixed. An unchecked box has no check status. In static HTML, the visible control is not a second tab stop. On the mini program, an empty description is left off. On the mini program, the check mark is hidden from the name.`,
  switch: (key) => `${key} toggles the switch. The switch receives the keys. An omitted name is Switch. A passed aria-label names the switch. A switch that is on is visible as On. A switch that is off has no check status. In static HTML, the visible control is not a second tab stop. On the mini program, an empty description is left off. On the mini program, a read-only switch sets aria-readonly.`,
  slider: (key) => `${key} increases the value by one step. PageUp increases by ten steps. PageDown decreases by ten steps. Shift with an arrow moves by ten steps. Home jumps to the minimum. End jumps to the maximum. The slider receives the keys. The current value is visible. Two thumbs read both values, separated by to. An omitted name is Value. A passed aria-label names the slider. aria-labelledby suppresses the omitted name. A passed aria-label stays. On the mini program, a passed aria-label stays, and aria-label is left off when only aria-labelledby is set. On the mini program, the slider exposes its minimum, maximum, and current value. An empty value does not set aria-valuenow. On the mini program, a read-only slider sets aria-readonly.`,
}

