export function contractNote(slug: string) {
  return contract[slug] ?? contract[noteAlias[slug]] ?? null
}

export function keyboardNote(slug: string) {
  const key = slugWidget[slug] ? slug : (noteAlias[slug] ?? slug)
  const widget = slugWidget[key]
  if (widget) return sentence[widget](keyLabel(widgetKeyContract[widget]))
  return extra[key] ?? null
}

function noteItems(note: string) {
  return note
    .split(/(?<=\.)\s+(?=[A-Z0-9])/)
    .map((item) => item.trim())
    .filter(Boolean)
}

export function KeyboardNote({ slug }: { slug: string }) {
  const note = keyboardNote(slug)
  if (!note) return null
  const items = noteItems(note)
  return (
    <section id="keyboard" className="mt-14 space-y-4">
      <DocsSectionHeader
        title="Keyboard"
        kicker="键盘与焦点"
        subtitle="跨 React、Vue 与小程序共享的交互与可读名称约定。"
      />
      <DocsProsePanel>
        <ul className="m-0 list-disc space-y-2 pl-4">
          {items.map((item, index) => (
            <li key={`${index}-${item.slice(0, 24)}`}>{item}</li>
          ))}
        </ul>
      </DocsProsePanel>
    </section>
  )
}

export function ContractNote({ slug }: { slug: string }) {
  const note = contractNote(slug)
  if (!note) return null
  return (
    <section id="contract" className="mt-14 space-y-4">
      <DocsSectionHeader
        title="Contract"
        kicker="行为契约"
        subtitle="inspect 与运行时应对齐的 props、状态与无障碍语义。"
      />
      <DocsProsePanel>
        <ul className="m-0 list-disc space-y-2 pl-4">
          {noteItems(note).map((item, index) => (
            <li key={`${index}-${item.slice(0, 24)}`}>{item}</li>
          ))}
        </ul>
      </DocsProsePanel>
    </section>
  )
}
